const { randomUUID } = require('crypto');
const envelope = $input.first().json;
const handoff = envelope.performance_handoff;
const text = handoff.extracted_text;
const decode = (value) => String(value ?? '').replace(/<[^>]+>/g, ' ').replace(/&gt;/g, '>').replace(/&lt;/g, '<').replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const numberPt = (value) => { const clean = decode(value).replace(/R\$\s*/gi, '').replace(/\./g, '').replace(',', '.').replace(/[^0-9+\-.]/g, ''); if (!clean || !/[0-9]/.test(clean)) return null; const parsed = Number(clean); return Number.isFinite(parsed) ? parsed : null; };
const rowMatches = [...text.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)];
const indicators = [];
for (const match of rowMatches) {
  const cells = [...match[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)].map((cell) => decode(cell[1]));
  if (cells.length < 11) continue;
  const name = cells[0];
  if (!name || /^(\+\s*)?produto$/i.test(name) || /indicadores|legendas|negócios|qualidade|gestão de risco|clientes/i.test(name)) continue;
  const weight = numberPt(cells[1]); const metric = cells[2]; const baseDate = cells[3]; const target = numberPt(cells[4]); const achieved = numberPt(cells[5]); const attainment = numberPt(cells[6]); const reference = numberPt(cells[7]); const projection = numberPt(cells[8]); const dailyNeed = numberPt(cells[9]); const points = numberPt(cells[10]);
  if (weight === null || !metric || !['QTD','PROD','PERC','PONT'].includes(metric.toUpperCase())) continue;
  indicators.push({indicator_id: `pobj-${String(indicators.length + 1).padStart(3,'0')}`, name, weight, metric: metric.toUpperCase(), base_date: /^\d{2}\/\d{2}\/\d{4}$/.test(baseDate) ? baseDate : null, target, achieved, attainment_percent: attainment, reference_percent: reference, projected_final_percent: projection, daily_need: dailyNeed, reported_points: points, value_origin: 'DOCUMENT_REPORTED', locator: `document://${handoff.source?.content_hash ?? 'unknown'}#row-${indicators.length + 1}`});
}
const period = text.match(/MENSAL\s*-\s*([A-ZÇÃÕÉÍÓÚ]+)\/(20\d{2})/i);
const base = text.match(/Base\s+(\d{2}\/\d{2}\/20\d{2})/i);
const headline = text.match(/PONTOS possíveis atingidos % ating\. acelora % final\s*([\d.,-]+)\s+([\d.,-]+)\s+([\d.,-]+)\s+([\d.,-]+)\s+([\d.,-]+)/i);
const summary = {period: period ? `${period[1].toUpperCase()}/${period[2]}` : null, base_date: base?.[1] ?? null, possible_points: headline ? numberPt(headline[1]) : null, achieved_points: headline ? numberPt(headline[2]) : null, attainment_percent: headline ? numberPt(headline[3]) : null, accelerator_points: headline ? numberPt(headline[4]) : null, final_points: headline ? numberPt(headline[5]) : null};
const recon = {schema_version: '1.0.0', reconciliation_id: randomUUID(), capability: 'PERFORMANCE_SOURCES_RECONCILIATION', source_count: 1, source_status: 'SINGLE_AUTHORIZED_DOCUMENT', conflicts: [], indicator_count: indicators.length, period: summary.period, base_date: summary.base_date};
return [{json: {...envelope, performance_reconciliation: recon, performance_observations: {schema_version: '1.0.0', summary, indicators, provenance: {source_hash: handoff.source?.content_hash, extraction_method: handoff.source?.extraction_method, evidence_count: handoff.evidence?.length ?? 0}}}}];

const { randomUUID } = require('crypto');
const envelope = $input.first().json;
const observations = envelope.performance_observations;
const weighted = observations.indicators.filter((item) => item.weight > 0);
const withAttainment = weighted.filter((item) => item.attainment_percent !== null);
const candidates = withAttainment.filter((item) => item.attainment_percent < 100).sort((a,b) => (a.attainment_percent ?? 999) - (b.attainment_percent ?? 999)).slice(0,5);
const strengths = withAttainment.filter((item) => item.attainment_percent >= 100).sort((a,b) => (b.reported_points ?? 0) - (a.reported_points ?? 0)).slice(0,3);
const missing = weighted.filter((item) => item.target === null || item.achieved === null || item.attainment_percent === null);
const findings = [];
if (observations.summary.final_points !== null) findings.push({finding_id: randomUUID(), topic: 'pobj_score_reportado', statement: `O documento reporta ${observations.summary.final_points.toFixed(2)} pontos finais no período ${observations.summary.period ?? 'não identificado'}, base ${observations.summary.base_date ?? 'não identificada'}.`, inference_type: 'SOURCE_REPORTED', evidence_quality: 'SUFFICIENT'});
if (candidates.length) findings.push({finding_id: randomUUID(), topic: 'indicadores_abaixo_da_meta', statement: `${candidates.length} indicadores ponderados aparecem abaixo de 100% entre os candidatos prioritários: ${candidates.map((item) => `${item.name} (${item.attainment_percent.toFixed(2)}%)`).join('; ')}.`, inference_type: 'DETERMINISTIC', evidence_quality: 'SUFFICIENT'});
if (strengths.length) findings.push({finding_id: randomUUID(), topic: 'indicadores_em_meta', statement: `Destaques em ou acima de 100%: ${strengths.map((item) => `${item.name} (${item.attainment_percent.toFixed(2)}%)`).join('; ')}.`, inference_type: 'DETERMINISTIC', evidence_quality: 'SUFFICIENT'});
const gaps = missing.map((item) => ({field: item.name, reason_code: 'SOURCE_FIELD_NOT_AVAILABLE', impact: 'Não é seguro calcular gap ou cenário deste indicador.', requires_manual_review: false}));
const actions = candidates.slice(0,3).map((item,index) => ({action_id: randomUUID(), action: `Revisar alavancas para ${item.name}; o documento registra ${item.attainment_percent.toFixed(2)}% de atingimento${item.daily_need !== null ? ` e necessidade diária de ${item.daily_need.toLocaleString('pt-BR')}` : ''}.`, priority: index === 0 ? 'P1' : 'P2', requires_human_approval: false, execution_authorization: 'NOT_APPLICABLE', related_indicator_id: item.indicator_id}));
const complete = observations.indicators.length > 0 && observations.summary.base_date !== null;
const assessment = {schema_version: '1.0.0', assessment_id: randomUUID(), manager: 'GERENTE_GERAL_PERFORMANCE', producer_version: '1.0.0', execution_status: 'SUCCESS', decision_status: complete ? 'READY' : 'MANUAL_REVIEW_REQUIRED', capabilities_executed: ['PERFORMANCE_SOURCES_RECONCILIATION','PERFORMANCE_SCORING_STATE','PERFORMANCE_GAP_SCENARIOS'], period: observations.summary.period, base_date: observations.summary.base_date, summary: observations.summary, indicators: observations.indicators, priority_candidates: candidates, strengths, findings, data_gaps: gaps, recommended_actions: actions, calculation_policy: {reported_values_preserved: true, recalculated_points: false, reason: 'Pontos permanecem os reportados pela fonte até a regra específica de cada indicador estar homologada.'}, security: {external_effects_allowed: false}};
return [{json: {...envelope, performance_analysis: assessment}}];

const envelope = $input.first().json;
const analysis = envelope.performance_analysis;
const normalize = (value) => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const direction = (item) => { const name = normalize(item.name); if (/vencidos|inadimpl|perda|atraso/.test(name)) return 'LOWER_IS_BETTER'; if (/captacao|seguro|capitalizacao|folha|boleto|pix|consorcio|cart(ao|oes)|faturamento|open finance|crescimento|conquista|reativacao|credito|cielo|centralizacao|encanta|conecta/.test(name)) return 'HIGHER_IS_BETTER'; return 'UNKNOWN'; };
analysis.indicators = analysis.indicators.map((item) => ({...item, goal_direction: direction(item)}));
const comparable = analysis.indicators.filter((item) => item.weight > 0 && item.attainment_percent !== null && item.goal_direction === 'HIGHER_IS_BETTER');
analysis.priority_candidates = comparable.filter((item) => item.attainment_percent < 100).sort((a,b) => a.attainment_percent - b.attainment_percent).slice(0,5);
analysis.strengths = comparable.filter((item) => item.attainment_percent >= 100).sort((a,b) => (b.reported_points ?? 0) - (a.reported_points ?? 0)).slice(0,3);
analysis.data_gaps.push(...analysis.indicators.filter((item) => item.weight > 0 && item.goal_direction === 'UNKNOWN').map((item) => ({field: item.name, reason_code: 'GOAL_DIRECTION_NOT_HOMOLOGATED', impact: 'Indicador preservado, mas excluído do ranking até homologar a direção da meta.', requires_manual_review: false})));
analysis.recommended_actions = analysis.priority_candidates.slice(0,3).map((item,index) => ({action_id: `candidate-${item.indicator_id}`, action: `Revisar alavancas para ${item.name}; o documento registra ${item.attainment_percent.toFixed(2)}% de atingimento${item.daily_need !== null ? ` e necessidade diária de ${item.daily_need.toLocaleString('pt-BR')}` : ''}.`, priority: index === 0 ? 'P1' : 'P2', requires_human_approval: false, execution_authorization: 'NOT_APPLICABLE', related_indicator_id: item.indicator_id}));
analysis.findings = analysis.findings.filter((item) => !['indicadores_abaixo_da_meta','indicadores_em_meta'].includes(item.topic));
if (analysis.priority_candidates.length) analysis.findings.push({finding_id: `gaps-${analysis.assessment_id}`, topic: 'indicadores_abaixo_da_meta', statement: `${analysis.priority_candidates.length} indicadores comparáveis aparecem abaixo de 100%: ${analysis.priority_candidates.map((item) => `${item.name} (${item.attainment_percent.toFixed(2)}%)`).join('; ')}.`, inference_type: 'DETERMINISTIC', evidence_quality: 'SUFFICIENT'});
if (analysis.strengths.length) analysis.findings.push({finding_id: `strengths-${analysis.assessment_id}`, topic: 'indicadores_em_meta', statement: `Destaques comparáveis em ou acima de 100%: ${analysis.strengths.map((item) => `${item.name} (${item.attainment_percent.toFixed(2)}%)`).join('; ')}.`, inference_type: 'DETERMINISTIC', evidence_quality: 'SUFFICIENT'});
analysis.ranking_policy = {version: '1.0.0', unknown_direction_excluded: true, lower_is_better_excluded_from_higher_ranking: true};
return [{json: {...envelope, performance_analysis: analysis}}];

const envelope = $input.first().json;
const analysis = envelope.performance_analysis;
const normalize = (value) => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const round2 = (value) => Math.round((value + Number.EPSILON) * 100) / 100;
const validations = [];
for (const item of analysis.indicators) {
  const name = normalize(item.name);
  let ruleId = null; let expected = null;
  if (/consorcio \(expert\)/.test(name) && item.attainment_percent !== null && item.weight > 0) { ruleId = 'N3_CONSORCIO_EXPERT_LINEAR'; expected = round2(item.weight * Math.min(Math.max(item.attainment_percent, 0), 100) / 100); }
  else if (/^open finance pj$/.test(name) && item.attainment_percent !== null && item.weight > 0) { ruleId = 'OPEN_FINANCE_PJ_BINARY'; expected = item.attainment_percent >= 100 ? round2(item.weight) : 0; }
  if (!ruleId) continue;
  const reported = item.reported_points; const difference = reported === null ? null : round2(reported - expected);
  validations.push({indicator_id: item.indicator_id, indicator_name: item.name, rule_id: ruleId, policy_id: 'POBJ_SCORING_2026_H2', policy_version: '1.0.0', validation_mode: 'SHADOW_COMPARE_ONLY', expected_points: expected, reported_points: reported, difference, status: reported !== null && Math.abs(difference) <= 0.01 ? 'MATCH' : 'REVIEW_REQUIRED'});
}
analysis.rule_validation = {policy_id: 'POBJ_SCORING_2026_H2', policy_version: '1.0.0', runtime_policy_status: 'APPROVED_SOURCE_NOT_RUNTIME_ACTIVE', source_values_overwritten: false, validations, matched: validations.filter((item) => item.status === 'MATCH').length, review_required: validations.filter((item) => item.status !== 'MATCH').length};
if (analysis.rule_validation.review_required > 0) analysis.data_gaps.push({field: 'rule_validation', reason_code: 'REPORTED_POINTS_DIVERGE_FROM_EXPLICIT_RULE', impact: 'A divergência deve ser revisada antes de ativar cálculo automático.', requires_manual_review: true});
return [{json: {...envelope, performance_analysis: analysis}}];

const envelope = $input.first().json;
const analysis = envelope.performance_analysis;
const normalize = (value) => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const exceptionPattern = /consorcio|cart(ao|oes)|seguro|encanta|vencidos|open finance|acelera|conecta|capital de giro total pj - mes|cdc velculos pj - mes|conquista de clientes pj - mes|capitalizacao pu \+ pm/;
const round2 = (value) => Math.round((value + Number.EPSILON) * 100) / 100;
const calculate = (attainment, weight) => { const bounded = Math.min(Math.max(0, attainment), 150); const multiplier = bounded < 70 ? 0 : bounded < 80 ? 0.5 : bounded < 90 ? 0.75 : 1; return {points: round2(weight * bounded / 100 * multiplier), bounded_attainment_percent: bounded, multiplier}; };
const validations = analysis.indicators.filter((item) => item.weight > 0 && item.projected_final_percent !== null && !exceptionPattern.test(normalize(item.name))).map((item) => { const calculated = calculate(item.projected_final_percent, item.weight); const difference = item.reported_points === null ? null : round2(item.reported_points - calculated.points); return {indicator_id: item.indicator_id, indicator_name: item.name, rule_id: 'POBJ_GENERAL_WEIGHT_ATTAINMENT_MULTIPLIER', policy_id: 'POBJ_SCORING_2026_H2', policy_version: '1.1.0', attainment_field: 'projected_final_percent', projected_final_percent: item.projected_final_percent, expected_points: calculated.points, reported_points: item.reported_points, difference, multiplier: calculated.multiplier, bounded_attainment_percent: calculated.bounded_attainment_percent, status: item.reported_points !== null && Math.abs(difference) <= 0.01 ? 'MATCH' : 'REVIEW_REQUIRED'}; });
const general = {runtime_status: 'RUNTIME_ACTIVE', authorized_by: 'Rafael', external_effects_allowed: false, source_values_overwritten: false, eligible: validations.length, matched: validations.filter((item) => item.status === 'MATCH').length, review_required: validations.filter((item) => item.status !== 'MATCH').length, validations};
analysis.general_rule_validation = general;
analysis.rule_validation.policy_version = '1.1.0';
analysis.rule_validation.runtime_policy_status = 'RUNTIME_ACTIVE';
if (general.review_required > 0) { analysis.decision_status = 'MANUAL_REVIEW_REQUIRED'; analysis.data_gaps.push({field: 'general_rule_validation', reason_code: 'GENERAL_RULE_DIVERGENCE', impact: 'Pontuação reportada diverge da política ativa; cálculo não deve ser promovido para o Estado.', requires_manual_review: true}); }
return [{json: {...envelope, performance_analysis: analysis}}];
